pets = {}
def handle(method, path, body=None):
    pid = 7 if path == "/pets" else int(path.split("/")[2])
    if method == "POST":
        pets[pid] = body
        return 201, pid
    if pid not in pets:
        return 404, "not found"
    if method == "DELETE":
        del pets[pid]
        return 204, "(no body)"
    return 200, pets[pid]

for method, path in [("POST", "/pets"), ("GET", "/pets/7"), ("DELETE", "/pets/7"), ("GET", "/pets/7")]:
    print(method, path, "->", *handle(method, path, {"name": "Rex"}))
